module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
reg [7:0] temp [0:7];
reg [15:0] sum [0:3];

reg [2:0] mul_en_out_reg;
reg [15:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 8'b0;
        mul_b_reg <= 8'b0;
        mul_en_out_reg <= 3'b0;
        mul_out_reg <= 16'b0;
        for (integer i = 0; i < 4; i++) begin
            sum[i] <= 16'b0;
        end
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
        end

        for (integer i = 0; i < 4; i++) begin
            temp[i*2] <= mul_a_reg & (mul_b_reg >>> (i*2));
            temp[i*2 + 1] <= mul_a_reg & (mul_b_reg >>> ((i*2) + 1));
        end

        sum[0] <= temp[0] + temp[1];
        sum[1] <= temp[2] + temp[3];
        sum[2] <= temp[4] + temp[5];
        sum[3] <= temp[6] + temp[7];

        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
    end
end

assign mul_en_out = mul_en_out_reg[2];
assign mul_out = mul_out_reg;

endmodule
